        gcd, x1, y1 = gcd_extended(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = gcd_extended(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # Chinese Remainder Theorem
    x = 0
    M = 1
    for m in moduli:
        M *= m

    for i in range(len(moduli)):
        Mi = M // moduli[i]
